/**
 * Daily snapshot of The Fulfillment Lab (GFS) warehouse inventory per
 * (connectorId, localdate, productId, warehouseId). localdate is part of the
 * key deliberately: the endpoint carries no timestamp and only ever reports
 * the present, so on-hand history is unrecoverable for any day that is
 * overwritten or missed.
 *
 * Read-only: it is not in `WritableDB`.
 */
export interface DbTable_tfl_products_v1__WarehouseInventory {
	/**
	 * `row.allocated`, reserved at this warehouse on `localdate`. MEASURED integral
	 */
	allocated: number;
	/**
	 * `row.available`, sellable at this warehouse on `localdate`. MEASURED integral
	 */
	available: number;
	/**
	 * The Databrill connector id of The Fulfillment Lab connector that fetched this snapshot row
	 */
	connectorId: string;
	/**
	 * OUR row bookkeeping: when this row was first written. Not a GFS field
	 */
	createdAt: InstantColumn;
	/**
	 * The full verbatim warehouse-inventory row from the API; persisted as JSONB, including the `productName` that is deliberately not promoted here. Typed `Unknown` because no copied-in API type exists to pin a struct against
	 */
	doc: Json;
	/**
	 * SOURCE ZONE: AMERICA/NEW_YORK. The `yyyy-MM-dd` Eastern calendar day of OUR FETCH, not of a payload field — the endpoint carries no timestamp. Not the UTC day: a poll between midnight UTC and midnight Eastern would be mislabelled. Stored DATE, matching the repo's `localdate` convention so joins to `amzreport_ALL_ORDERS.localdate` line up
	 */
	localdate: PlainDateColumn;
	/**
	 * `row.productId`, joining to `tfl_products_v1__Inventory.productId` by convention
	 */
	productId: number;
	/**
	 * `row.quantity`, on hand at this warehouse on `localdate`. MEASURED integral
	 */
	quantity: number;
	/**
	 * OUR row bookkeeping: when this row was last written. Not a GFS field
	 */
	updatedAt: InstantColumn;
	/**
	 * `row.warehouseId`. In the key even for an account with a single warehouse: the endpoint exists to split by warehouse, and a key cannot be widened later because these tables have no ALTER path
	 */
	warehouseId: number;
	/**
	 * `row.warehouseName`. Nullable per the connector-wide rule that a promoted string is nullable unless the corpus proves otherwise
	 */
	warehouseName: string | null;
}

/**
 * One The Fulfillment Lab (GFS) shipment per (connectorId, id), with its
 * fulfilment, container, shipping and total charges. cartOrderIds is an array
 * because GFS can join several orders into one shipment, and it must not be
 * reduced to a single id.
 *
 * Read-only: it is not in `WritableDB`.
 */
export interface DbTable_tfl_shipments_v1__Shipment {
	/**
	 * `shipment.cartOrderIds` — the MERCHANT cart order ids this shipment covers, stored as TEXT[]. A shipment can carry more than one id, so multi-order shipments occur and the array must not be flattened. Joins to `tfl_orders_v1__Order.cartOrderId`
	 */
	cartOrderIds: string[];
	/**
	 * The Databrill connector id of The Fulfillment Lab connector that fetched this shipment
	 */
	connectorId: string;
	/**
	 * `shipment.containerCharge`. MEASURED non-integral; DOUBLE PRECISION
	 */
	containerCharge: number;
	/**
	 * OUR row bookkeeping: when this row was first written. Not a GFS field
	 */
	createdAt: InstantColumn;
	/**
	 * The full verbatim shipment payload from the API; persisted as JSONB, including the raw `shipDate` string. Typed `Unknown` because no copied-in API type exists to pin a struct against
	 */
	doc: Json;
	/**
	 * `shipment.fulfillmentCharge`. MEASURED non-integral; DOUBLE PRECISION
	 */
	fulfillmentCharge: number;
	/**
	 * `shipment.id`, GFS's own shipment id. Unique
	 */
	id: number;
	/**
	 * SOURCE ZONE: US EASTERN WALL TIME (America/New_York), localised on ingestion. `shipment.shipDate` carries NO offset designator, so nothing in the value reveals its zone; MEASURED to sit in the Eastern family alongside `order.shipDate`. The raw string survives in `doc`, so the decision is reversible without a re-fetch
	 */
	shipDate: InstantColumn;
	/**
	 * `shipment.shippingCharge`. MEASURED non-integral; DOUBLE PRECISION
	 */
	shippingCharge: number;
	/**
	 * `shipment.totalCharge`. MEASURED non-integral; DOUBLE PRECISION
	 */
	totalCharge: number;
	/**
	 * OUR row bookkeeping: when this row was last written. Not a GFS field
	 */
	updatedAt: InstantColumn;
}

/**
 * The Walmart seller's business identity — legal name, business registration
 * number and country of incorporation — one row per connector.
 *
 * Read-only: it is not in `WritableDB`.
 */
export interface DbTable_wmt_account_v3__profile {
	businessRegistrationNumber: string | null;
	/**
	 * OURS, not from the payload: the Databrill connector id of the Walmart connector whose entity-match profile this is; the key that scopes this row to its connector (a globally unique UUIDv7, one per workspace, so no workspace column is needed in the primary key)
	 */
	connectorId: string;
	countryOfIncorporation: string | null;
	createdAt: InstantColumn;
	/**
	 * The verbatim entitymatchprofile response body (the `body` wrapper plus `status`). Persisted as JSONB; typed `Unknown` because Walmart publishes no API specification, so there is no generated type to assert the shape against
	 */
	doc: Json;
	name: string | null;
	/**
	 * OURS, not from the payload: the time this profile was fetched from Walmart
	 */
	time: InstantColumn;
	updatedAt: InstantColumn;
}

/**
 * Latest known Walmart WFS inventory for one SKU at one ship node, keyed
 * (connectorId, sku, shipNodeType, shipNode). Rows are upserted in place and
 * never deleted, so a SKU that disappears from the feed keeps its last-known
 * quantities: compare each row's time against the connector's latest snapshot
 * time and treat an older row as stale, not as zero.
 *
 * Read-only: it is not in `WritableDB`.
 */
export interface DbTable_wmt_inventory_v3__Wfs {
	availToSellQty: number | null;
	/**
	 * OURS, not from the payload: the Databrill connector id of the Walmart connector that took the snapshot; the key that scopes this row to its connector
	 */
	connectorId: string;
	createdAt: InstantColumn;
	/**
	 * THE NODE (`node`) verbatim, NOT the item — the row's grain IS the node, so the node is its verbatim payload. Consequence: sibling nodes of the same item are not recoverable from any single row's doc, and sku/offerId appear only as their own columns. Persisted as JSONB; typed `Unknown` because no copied-in API type exists to pin a struct against
	 */
	doc: Json;
	firstInStockDate: InstantColumn | null;
	modifiedDate: InstantColumn | null;
	offerId: string | null;
	onHandQty: number | null;
	/**
	 * NODE-level (`node.shipNode`). The node's IDENTIFIER — distinct from shipNodeType, which is its class. IN THE PRIMARY KEY: two nodes of the same shipNodeType but different shipNode are DISTINCT rows, not a collision. The API marks it optional; when the payload omits it the Worker writes the empty-string SENTINEL '' (a PK column cannot be NULL), so '' means `node.shipNode` was absent
	 */
	shipNode: string;
	/**
	 * NODE-level (`node.shipNodeType`). From the RESPONSE BODY, NEVER from the request: /v3/fulfillment/inventory takes no shipNodeType parameter (that is /v3/orders). The node's CLASS, not its identifier
	 */
	shipNodeType: string;
	/**
	 * ITEM-level (`item.sku`)
	 */
	sku: string;
	/**
	 * OURS, not from the payload: the snapshot time of the latest run that touched this row. NOT IN THE PRIMARY KEY — it is overwritten on every run rather than appended. It is the ONLY staleness signal this table has: a row whose time predates the most recent inventory run was not refreshed by that run, so treat it as stale, not as zero
	 */
	time: InstantColumn;
	updatedAt: InstantColumn;
}

/**
 * One Walmart Marketplace order header per (connectorId, purchaseOrderId),
 * with the full payload in doc. There is deliberately no status column:
 * Walmart reports status only per line, on wmt_orders_v3__OrderLine.
 *
 * Read-only: it is not in `WritableDB`.
 */
export interface DbTable_wmt_orders_v3__Order {
	/**
	 * The Databrill connector id of the Walmart connector that fetched this order
	 */
	connectorId: string;
	createdAt: InstantColumn;
	customerEmailId: string | null;
	customerOrderId: string | null;
	/**
	 * The full verbatim order payload from the API; persisted as JSONB. Typed `Unknown` rather than a struct because no copied-in API type exists to pin a struct against, and because the payload's undeclared extras are exactly what this column exists to retain
	 */
	doc: Json;
	estimatedDeliveryDate: InstantColumn | null;
	estimatedShipDate: InstantColumn | null;
	/**
	 * Walmart's purchase order identifier; `order.purchaseOrderId`
	 */
	purchaseOrderId: string;
	shipNodeType: string | null;
	shippingInfo: Json | null;
	/**
	 * The order's orderDate; `order.orderDate`, which arrives as EPOCH MILLISECONDS (inventory's dates are ISO 8601 strings — the two families are opposite). No PST/PDT conversion is applied or needed
	 */
	time: InstantColumn;
	updatedAt: InstantColumn;
}

/**
 * One line of a Walmart Marketplace order, keyed (connectorId,
 * purchaseOrderId, lineNumber). status, trackingNumber and carrierName are
 * taken from the first order-line-status element; the full array is kept in
 * doc, so a quantity-weighted status can be recomputed without a re-fetch.
 *
 * Read-only: it is not in `WritableDB`.
 */
export interface DbTable_wmt_orders_v3__OrderLine {
	carrierName: string | null;
	/**
	 * The Databrill connector id of the Walmart connector that fetched this line
	 */
	connectorId: string;
	createdAt: InstantColumn;
	/**
	 * The full verbatim orderLine payload, INCLUDING the complete orderLineStatus array that the `status` column collapses to element [0]; persisted as JSONB. Typed `Unknown` rather than a struct because no copied-in API type exists to pin a struct against
	 */
	doc: Json;
	fulfillmentType: string | null;
	/**
	 * `orderLine.lineNumber`; a string in the payload, not a number
	 */
	lineNumber: string;
	productName: string | null;
	/**
	 * The parent order's `order.purchaseOrderId`
	 */
	purchaseOrderId: string;
	/**
	 * `orderLine.orderLineQuantity.amount`, which arrives as a STRING and is parsed to an int
	 */
	quantity: number;
	shippingPrice: Numeric | null;
	/**
	 * `orderLine.item.sku`
	 */
	sku: string;
	/**
	 * `orderLineStatuses.orderLineStatus[0].status`, falling back to the literal 'Unknown'. This is the ONLY place Walmart exposes order status — the order header carries none. Examples: Created, Acknowledged, Shipped, Delivered, Cancelled
	 */
	status: string;
	taxAmount: Numeric | null;
	/**
	 * The PARENT ORDER's orderDate (epoch millis inbound), copied onto the line so the line table can be scanned by order date without a join
	 */
	time: InstantColumn;
	trackingNumber: string | null;
	unitPrice: Numeric | null;
	updatedAt: InstantColumn;
}

